    18	export type CommitErrorKind =
    19	  "empty" | "rate_limit" | "timeout" | "unavailable" | "validation" | "unknown";
    20	
    21	/**
    22	 * A search that found commits. The tuple is the invariant: a successful result with an empty list
    23	 * was representable before, and every consumer paid for it with a defensive check that could never
    24	 * fire -- `result.found && result.commits.length > 0` in the page, a `if (!firstCommit) return null`
    25	 * in the results view. `found` alone is now enough.
    26	 */
    27	export type CommitSearchSuccess = {
    28	  found: true;
    29	  commits: [CommitInfo, ...CommitInfo[]];
    30	  /**
    31	   * GitHub reported `incomplete_results`, meaning the search timed out before scanning every
    32	   * commit. An earlier commit may exist that this result misses, so partial results are surfaced
    33	   * to the visitor and never cached.
    34	   */
    35	  incomplete?: boolean;
    36	};
    37	
    38	/**
    39	 * A search that returned nothing usable. `error` and `errorKind` are required rather than optional:
    40	 * every failure the server action produces carries both, and leaving them optional meant each
    41	 * reader deciding for itself what an absent kind meant.
    42	 *
    43	 * `incomplete` lives on both variants deliberately. A search can time out before scanning every
    44	 * commit and return nothing, which is a failure the visitor should be told is unfinished rather
    45	 * than told is an absence of commits.
    46	 */
    47	export type CommitSearchFailure = {
    48	  found: false;
    49	  commits: [];
    50	  error: string;
    51	  errorKind: CommitErrorKind;
    52	  incomplete?: boolean;
    53	};
    54	
    55	/**
    56	 * Discriminated on `found`, so narrowing gives a reader the right shape without a cast and makes
    57	 * an impossible combination -- a failure kind on a success, commits on a failure -- fail to
    58	 * compile rather than fail a runtime check somebody remembered to write.
    59	 *
    60	 * The wire format is unchanged. Tuples are erased at runtime, so what the Server Action serializes
    61	 * is the same JSON it always was, and a result cached by an older instance still deserializes.
    62	 */
    63	export type CommitData = CommitSearchSuccess | CommitSearchFailure;
    64	
    65	/**
    66	 * The two failure messages the search reaches for when GitHub returns nothing usable. They live
    67	 * beside the constructor that carries them, and are shared rather than copied because the browser
    68	 * fixtures assert on the same wording: a second copy would let the real path and the fixture path
    69	 * describe the same outcome differently, which is the drift `commitSearchMocksEnabled` exists to
    70	 * prevent one level down.
    71	 */
    72	export const EMPTY_COMMIT_SEARCH_MESSAGE =
    73	  "No public commits found for this user (or indexing is delayed).";
    74	export const INCOMPLETE_COMMIT_SEARCH_MESSAGE =
    75	  "GitHub could not finish this search, so no commits were returned yet.";
    76	
    77	/**
    78	 * Builds a failure. Paired here with `toCommitSearchSuccess` below so both constructors of the
    79	 * union live with the union, and so callers outside the server action can build one -- a
    80	 * `"use server"` module cannot export a synchronous helper, which is what put this here rather
    81	 * than leaving it in `actions.ts`.
