    84	  error: string,
    85	  errorKind: CommitErrorKind,
    86	  incomplete = false,
    87	): CommitSearchFailure {
    88	  return { found: false, error, errorKind, ...(incomplete ? { incomplete } : {}), commits: [] };
    89	}
    90	
    91	/**
    92	 * Builds a success, or returns `null` when there is nothing to succeed with.
    93	 *
    94	 * This exists so the non-empty invariant is established in exactly one place. TypeScript does not
    95	 * narrow `CommitInfo[]` to a non-empty tuple from a `length === 0` check, so without it every
    96	 * construction site would need its own assertion -- and an assertion is a promise the compiler
    97	 * cannot keep. Callers turn `null` into whichever empty-result message fits their context.
    98	 */
