   100	  commits: CommitInfo[],
   101	  options: { incomplete?: boolean } = {},
   102	): CommitSearchSuccess | null {
   103	  const [first, ...rest] = commits;
   104	
   105	  if (!first) return null;
   106	
   107	  return {
   108	    found: true,
   109	    commits: [first, ...rest],
   110	    ...(options.incomplete ? { incomplete: true } : {}),
   111	  };
