    34	function isProductionBuild() {
    35	  return process.env.NODE_ENV === "production";
    36	}
    37	
    38	export function buildReadinessPayload(env: EnvLike = process.env): ReadinessPayload {
    39	  return {
    40	    service: "my-first-commit",
    41	    commitSearchMocks: commitSearchMocksEnabled(env),
    42	  };
    43	}
    44	
    45	export async function GET() {
    46	  if (isProductionBuild()) {
    47	    return new Response(null, { status: 404 });
    48	  }
    49	
    50	  return Response.json(buildReadinessPayload(), {
    51	    status: 200,
    52	    headers: {
