     1	import type { CommitData, CommitInfo } from "./commitTypes";
     2	
     3	const COMMIT_SEARCH_CACHE_TTL_MS = 5 * 60 * 1000;
     4	const COMMIT_SEARCH_CACHE_MAX_ENTRIES = 100;
