    12	// requests it serves and starts empty on every cold start, so an in-process limit of N is
    13	// really N x instances. This reduces what abuse costs; it is not a quota guarantee, and
    14	// nothing here should be read as a global ceiling. See docs/production.md.
    15	//
    16	// The limiter never learns who a client is. It is handed an opaque key -- a salted hash, from
    17	// app/searchClientKey.ts -- and never sees the searched username at all, so neither can reach
    18	// a log line or an eviction decision from here.
    19	
    20	/**
    21	 * 30 searches per minute, per client. A person types a distinct valid GitHub handle every few
    22	 * seconds at most, so a sustained one every two seconds for a full minute is not a person; a
    23	 * visitor clicking every recent-search shortcut they have does not come close. It is also the
    24	 * documented ceiling for authenticated GitHub search, so a client past it is on its own able
    25	 * to spend the whole shared per-minute allowance.
    26	 */
    27	export const COMMIT_SEARCH_RATE_LIMIT_MAX_SEARCHES = 30;
    28	export const COMMIT_SEARCH_RATE_LIMIT_WINDOW_MS = 60_000;
    29	
    30	/**
    31	 * A map keyed by client is a memory-exhaustion vector if it is allowed to grow with the number
    32	 * of distinct keys that arrive, which is the one thing a flood produces cheaply. Idle clients
    33	 * are dropped as the window passes them and this caps what is left, so the map costs a bounded
    34	 * amount however many keys it is shown -- a few hundred kilobytes at most.
    35	 */
    36	export const COMMIT_SEARCH_RATE_LIMIT_MAX_CLIENTS = 500;
    37	
    38	/**
    39	 * Search times inside the current window, per client, oldest first. A rolling window rather
    40	 * than a counter that resets on a fixed boundary, which would let a client spend two full
    41	 * allowances back to back across one.
    42	 *
    43	 * Each list is capped by the limit itself: a refused search is not recorded, so a client that
    44	 * keeps trying does not grow its own entry.
    45	 */
    46	const recentSearchTimes = new Map<string, number[]>();
    47	
    48	function dropIdleClients(now: number) {
    49	  const windowStart = now - COMMIT_SEARCH_RATE_LIMIT_WINDOW_MS;
    50	
    51	  for (const [clientKey, searchTimes] of recentSearchTimes) {
    52	    const lastSearchedAt = searchTimes[searchTimes.length - 1];
    53	    if (lastSearchedAt === undefined || lastSearchedAt <= windowStart) {
    54	      recentSearchTimes.delete(clientKey);
    55	    }
    56	  }
    57	}
    58	
    59	function evictLeastRecentlyActiveClients() {
    60	  while (recentSearchTimes.size > COMMIT_SEARCH_RATE_LIMIT_MAX_CLIENTS) {
    61	    const oldestClientKey = recentSearchTimes.keys().next().value;
    62	    if (oldestClientKey === undefined) return;
    63	    recentSearchTimes.delete(oldestClientKey);
    64	  }
    65	}
    66	
    67	/**
    68	 * Records a search for `clientKey` and reports whether it is within the window's allowance.
    69	 *
    70	 * Eviction only ever forgets a client, which refills its allowance. That is the direction this
    71	 * has to fail in: a caller who can influence which key it is counted under must not be able to
    72	 * push another client into being refused.
    73	 */
    74	export function allowCommitSearch(clientKey: string, now = Date.now()): boolean {
    75	  const windowStart = now - COMMIT_SEARCH_RATE_LIMIT_WINDOW_MS;
    76	  const searchTimes = (recentSearchTimes.get(clientKey) ?? []).filter(
    77	    (searchedAt) => searchedAt > windowStart,
    78	  );
    79	
    80	  const allowed = searchTimes.length < COMMIT_SEARCH_RATE_LIMIT_MAX_SEARCHES;
    81	  if (allowed) searchTimes.push(now);
    82	
    83	  // Re-inserted so iteration order stays least-recently-active first, which is what eviction
    84	  // reads. A refused client is re-inserted too: being evicted is a reprieve, so the client
    85	  // being refused right now is the last one that should get it.
    86	  recentSearchTimes.delete(clientKey);
    87	  recentSearchTimes.set(clientKey, searchTimes);
    88	
    89	  dropIdleClients(now);
    90	  evictLeastRecentlyActiveClients();
    91	
    92	  return allowed;
    93	}
    94	
    95	export function clearCommitSearchRateLimit() {
    96	  recentSearchTimes.clear();
    97	}
    98	
    99	/** Test seam: proves the map stays bounded under a flood of distinct keys. */
   100	export function trackedCommitSearchClientCount() {
   101	  return recentSearchTimes.size;
   102	}
   103	
   104	/**
   105	 * Test seam: proves what is retained is an opaque key and nothing else -- no username, and no
   106	 * raw client identifier.
   107	 */
   108	export function trackedCommitSearchClientKeys() {
   109	  return [...recentSearchTimes.keys()];
   110	}
