     1	import { useCallback, useEffect, useRef, useState, useTransition } from "react";
     2	import type { CommitData } from "../_lib/commitTypes";
     3	import { clearStoredRecentSearches, getStoredRecentSearches } from "./recentSearches";
     4	import { getRetryFailureMessage } from "./resultMessages";
     5	import { runCommitSearch } from "./searchExecution";
     6	
     7	type RunSearchOptions = { updateUrl?: boolean; isRetry?: boolean };
     8	
     9	/**
    10	 * Owns the commit-search result lifecycle (result, last-searched username,
    11	 * recent searches, share status, and the busy state) so the page component can
    12	 * trigger a search with a single `runSearch` call instead of threading state
    13	 * setters through every handler.
    14	 *
    15	 * The busy flag is owned here rather than taken from `useTransition`. `isPending`
    16	 * stays true through the tail of a transition and through a search the visitor has
    17	 * abandoned, which would leave the search form disabled with nothing in flight to
    18	 * re-enable it.
    19	 */
    20	export function useCommitSearch() {
    21	  const [result, setResult] = useState<CommitData | null>(null);
    22	  const [lastSearchedUsername, setLastSearchedUsername] = useState("");
    23	  const [recentSearches, setRecentSearches] = useState<string[]>([]);
    24	  const [shareStatus, setShareStatus] = useState("");
    25	  const [isSearching, setIsSearching] = useState(false);
    26	  const [isRetrying, setIsRetrying] = useState(false);
    27	  const [retryError, setRetryError] = useState("");
    28	  const [retryStillPartial, setRetryStillPartial] = useState(false);
    29	  const [, startTransition] = useTransition();
    30	  const nextSearchIdRef = useRef(0);
    31	  const latestSearchIdRef = useRef(0);
    32	  const resultRef = useRef<CommitData | null>(null);
    33	
    34	  useEffect(() => {
    35	    resultRef.current = result;
    36	  }, [result]);
    37	
    38	  useEffect(() => {
    39	    const loadRecentSearches = window.setTimeout(() => {
    40	      setRecentSearches(getStoredRecentSearches());
    41	    }, 0);
    42	
    43	    return () => window.clearTimeout(loadRecentSearches);
    44	  }, []);
    45	
    46	  const runSearch = useCallback((searchUsername: string, options: RunSearchOptions = {}) => {
    47	    // Identity comes from its own counter rather than from the latest-search marker, so
    48	    // it cannot depend on when that marker is assigned. The marker moves separately, and
    49	    // only once the search actually started.
    50	    const searchId = ++nextSearchIdRef.current;
    51	    const isRetry = Boolean(options.isRetry);
    52	
    53	    const started = runCommitSearch(
    54	      searchUsername,
    55	      { updateUrl: options.updateUrl, source: isRetry ? "retry" : undefined },
    56	      {
    57	        isLatestSearch: () => searchId === latestSearchIdRef.current,
    58	        startTransition,
    59	        setLastSearchedUsername,
    60	        setShareStatus,
    61	        applyResult: (data) => {
    62	          setIsSearching(false);
    63	          setIsRetrying(false);
    64	
    65	          // A retry launched from the results view must not destroy the result the
    66	          // visitor is reading: a shared rate limit or timeout would otherwise replace
    67	          // their commits with an error screen for taking the retry the UI offered.
    68	          if (isRetry && !data.found && resultRef.current?.found) {
    69	            setRetryError(getRetryFailureMessage(data));
    70	            return;
    71	          }
    72	
    73	          // "Still" is only true if the previous result was itself partial. A retry from
    74	          // the error panel starts from a failure, so a first partial answer there is
    75	          // news rather than a repeat.
    76	          if (isRetry && data.found && data.incomplete && resultRef.current?.incomplete) {
    77	            setRetryStillPartial(true);
    78	          }
    79	          setResult(data);
    80	        },
    81	        setRecentSearches,
    82	      },
    83	    );
    84	
    85	    // Only claim the search once the layer below accepted it; a rejected username
    86	    // never settles, so a busy flag set here would never clear.
    87	    if (!started) return;
    88	
    89	    // Assigned after the call, which is safe only because `isLatestSearch` is first
    90	    // consulted after an await. A synchronous check would read the previous value and
    91	    // make the search discard itself.
    92	    latestSearchIdRef.current = searchId;
    93	    setIsSearching(true);
    94	    setIsRetrying(isRetry);
    95	    setRetryError("");
    96	    setRetryStillPartial(false);
    97	  }, []);
    98	
    99	  // Reset controls clear the result but cannot clear an in-flight request. Without this
   100	  // a slow search resolving afterwards would remount results over the page the visitor
   101	  // moved to, and the busy flag would outlive the search by up to the GitHub timeout.
   102	  const cancelPendingSearch = useCallback(() => {
   103	    latestSearchIdRef.current = ++nextSearchIdRef.current;
   104	    setIsSearching(false);
   105	    setIsRetrying(false);
   106	    setRetryError("");
   107	    setRetryStillPartial(false);
   108	  }, []);
   109	
   110	  const clearRecentSearches = useCallback(() => {
   111	    setRecentSearches([]);
   112	    clearStoredRecentSearches();
   113	  }, []);
   114	
   115	  return {
   116	    result,
   117	    setResult,
   118	    lastSearchedUsername,
   119	    setLastSearchedUsername,
   120	    recentSearches,
   121	    clearRecentSearches,
   122	    shareStatus,
   123	    setShareStatus,
   124	    isSearching,
   125	    isRetrying,
   126	    retryError,
   127	    retryStillPartial,
   128	    runSearch,
   129	    cancelPendingSearch,
   130	  };
   131	}
