     1	import type { Dispatch, SetStateAction, TransitionStartFunction } from "react";
     2	import { getCommits } from "../_lib/actions";
     3	import type { CommitData } from "../_lib/commitTypes";
     4	import { getUsernameValidationMessage, normalizeGitHubUsername } from "../_lib/username";
     5	import { trackAppEvent } from "./analytics";
     6	import { MAX_RECENT_SEARCHES } from "./constants";
     7	import { saveStoredRecentSearches } from "./recentSearches";
     8	import { updateSharedSearchUrl } from "./sharedSearch";
     9	
    10	type SearchSource = "user" | "shared_url" | "retry";
    11	
    12	type SearchOptions = {
    13	  updateUrl?: boolean;
    14	  source?: SearchSource;
    15	};
    16	
    17	type SearchHandlers = {
    18	  isLatestSearch: () => boolean;
    19	  startTransition: TransitionStartFunction;
    20	  setLastSearchedUsername: Dispatch<SetStateAction<string>>;
    21	  setShareStatus: Dispatch<SetStateAction<string>>;
    22	  // Takes the settled search rather than a state action: the caller decides whether a
    23	  // failed retry replaces what is on screen, which it cannot do from inside an updater.
    24	  // It is the single settle signal, so the caller can clear its own busy flag here.
    25	  applyResult: (result: CommitData) => void;
    26	  setRecentSearches: Dispatch<SetStateAction<string[]>>;
    27	};
    28	
    29	function unexpectedSearchError(): CommitData {
    30	  return {
    31	    found: false,
    32	    error: "GitHub commit search failed. Please try again.",
    33	    errorKind: "unknown",
    34	    commits: [],
    35	  };
    36	}
    37	
    38	/**
    39	 * Returns whether the search actually started. A caller that owns a busy flag must gate
    40	 * it on this: the guards below reject a username without ever settling, which would
    41	 * otherwise leave the UI busy with nothing in flight to clear it.
    42	 */
    43	export function runCommitSearch(
    44	  searchUsername: string,
    45	  options: SearchOptions = {},
    46	  {
    47	    isLatestSearch,
    48	    startTransition,
    49	    setLastSearchedUsername,
    50	    setShareStatus,
    51	    applyResult,
    52	    setRecentSearches,
    53	  }: SearchHandlers,
    54	): boolean {
    55	  const trimmedUsername = normalizeGitHubUsername(searchUsername);
    56	  if (!trimmedUsername) return false;
    57	  if (getUsernameValidationMessage(trimmedUsername)) return false;
    58	  if (options.updateUrl) updateSharedSearchUrl(trimmedUsername);
    59	
    60	  trackAppEvent("search_submitted", {
    61	    source: options.source ?? (options.updateUrl ? "user" : "shared_url"),
    62	  });
    63	  setLastSearchedUsername(trimmedUsername);
    64	  setShareStatus("");
    65	  startTransition(async () => {
    66	    let data: CommitData;
    67	    try {
    68	      data = await getCommits(trimmedUsername);
    69	    } catch {
    70	      data = unexpectedSearchError();
    71	    }
    72	    if (!isLatestSearch()) return;
    73	
    74	    applyResult(data);
    75	    trackAppEvent("search_completed", {
    76	      found: data.found,
    77	      error_kind: data.found ? "none" : data.errorKind,
    78	      commit_count: data.commits.length,
    79	      incomplete: Boolean(data.incomplete),
    80	    });
    81	    if (data.found) {
    82	      setRecentSearches((currentSearches) => {
    83	        const nextSearches = [
    84	          trimmedUsername,
    85	          ...currentSearches.filter(
    86	            (search) => search.toLowerCase() !== trimmedUsername.toLowerCase(),
    87	          ),
    88	        ].slice(0, MAX_RECENT_SEARCHES);
    89	
    90	        saveStoredRecentSearches(nextSearches);
    91	        return nextSearches;
    92	      });
    93	    }
    94	  });
    95	
    96	  return true;
    97	}
