     1	import type { CommitSearchFailure } from "../_lib/commitTypes";
     2	
     3	// Every helper here takes a failure rather than a result. They are only ever reached from the
     4	// error panel and the failed-retry path, and taking the union would mean each one re-deciding what
     5	// a success means -- which is what let `errorKind` be read off a successful result at all.
     6	
     7	type ResultMessage = {
