    59	
    60	/**
    61	 * Copy for a retry that failed while an earlier partial result is still on screen.
    62	 * `getResultMessage` cannot be reused here: it is written as standalone panel prose,
    63	 * so it runs to several sentences and its empty-search wording claims nothing came
    64	 * back -- which would contradict the commits rendered directly below the message.
    65	 */
    66	export function getRetryFailureMessage(result: CommitSearchFailure): string {
    67	  switch (result.errorKind) {
    68	    case "rate_limit":
    69	      return "GitHub is rate limiting searches right now, so wait a few minutes before searching again.";
    70	    case "timeout":
    71	      return "GitHub took too long to respond again, so give it a moment before retrying.";
    72	    case "unavailable":
