     7	type RunSearchOptions = { updateUrl?: boolean; isRetry?: boolean };
     8	
     9	/**
    10	 * Owns the commit-search result lifecycle (result, last-searched username,
    11	 * recent searches, share status, and the busy state) so the page component can
    12	 * trigger a search with a single `runSearch` call instead of threading state
    13	 * setters through every handler.
    14	 *
    15	 * The busy flag is owned here rather than taken from `useTransition`. `isPending`
    16	 * stays true through the tail of a transition and through a search the visitor has
    17	 * abandoned, which would leave the search form disabled with nothing in flight to
    18	 * re-enable it.
    19	 */
    20	export function useCommitSearch() {
    21	  const [result, setResult] = useState<CommitData | null>(null);
    22	  const [lastSearchedUsername, setLastSearchedUsername] = useState("");
    23	  const [recentSearches, setRecentSearches] = useState<string[]>([]);
    24	  const [shareStatus, setShareStatus] = useState("");
    25	  const [isSearching, setIsSearching] = useState(false);
    26	  const [isRetrying, setIsRetrying] = useState(false);
    27	  const [retryError, setRetryError] = useState("");
    28	  const [retryStillPartial, setRetryStillPartial] = useState(false);
    29	  const [, startTransition] = useTransition();
    30	  const nextSearchIdRef = useRef(0);
    31	  const latestSearchIdRef = useRef(0);
    32	  const resultRef = useRef<CommitData | null>(null);
    33	
    34	  useEffect(() => {
    35	    resultRef.current = result;
    36	  }, [result]);
    37	
    38	  useEffect(() => {
    39	    const loadRecentSearches = window.setTimeout(() => {
    40	      setRecentSearches(getStoredRecentSearches());
    41	    }, 0);
    42	
    43	    return () => window.clearTimeout(loadRecentSearches);
    44	  }, []);
    45	
    46	  const runSearch = useCallback((searchUsername: string, options: RunSearchOptions = {}) => {
    47	    // Identity comes from its own counter rather than from the latest-search marker, so
    48	    // it cannot depend on when that marker is assigned. The marker moves separately, and
    49	    // only once the search actually started.
    50	    const searchId = ++nextSearchIdRef.current;
    51	    const isRetry = Boolean(options.isRetry);
    52	
    53	    const started = runCommitSearch(
    54	      searchUsername,
    55	      { updateUrl: options.updateUrl, source: isRetry ? "retry" : undefined },
    56	      {
    57	        isLatestSearch: () => searchId === latestSearchIdRef.current,
    58	        startTransition,
    59	        setLastSearchedUsername,
    60	        setShareStatus,
    61	        applyResult: (data) => {
    62	          setIsSearching(false);
    63	          setIsRetrying(false);
    64	
