   115	  return {
   116	    result,
   117	    setResult,
   118	    lastSearchedUsername,
   119	    setLastSearchedUsername,
   120	    recentSearches,
   121	    clearRecentSearches,
   122	    shareStatus,
   123	    setShareStatus,
   124	    isSearching,
   125	    isRetrying,
   126	    retryError,
   127	    retryStillPartial,
   128	    runSearch,
   129	    cancelPendingSearch,
   130	  };
