    82	      setRecentSearches((currentSearches) => {
    83	        const nextSearches = [
    84	          trimmedUsername,
    85	          ...currentSearches.filter(
    86	            (search) => search.toLowerCase() !== trimmedUsername.toLowerCase(),
    87	          ),
    88	        ].slice(0, MAX_RECENT_SEARCHES);
