    44	export function getStoredRecentSearches() {
    45	  if (typeof window === "undefined") return [];
    46	
    47	  try {
    48	    const storedSearches: unknown = JSON.parse(
    49	      window.localStorage.getItem(RECENT_SEARCHES_STORAGE_KEY) ?? "[]",
    50	    );
    51	    if (!Array.isArray(storedSearches)) return [];
    52	
    53	    return sanitizeStoredSearches(storedSearches);
    54	  } catch {
    55	    return [];
    56	  }
    57	}
