     9	  description: string;
    10	};
    11	
    12	export function getResultMessage(result: CommitSearchFailure): ResultMessage {
    13	  switch (result.errorKind) {
    14	    case "rate_limit":
    15	      return {
    16	        title: "GitHub is asking us to slow down.",
    17	        description:
    18	          "GitHub temporarily limited commit search requests. Wait a few minutes, then try this username again.",
    19	      };
    20	    case "timeout":
    21	      return {
    22	        title: "GitHub took too long to respond.",
    23	        description:
    24	          "The request timed out before GitHub finished searching. Try again now, or give GitHub a moment if it keeps happening.",
    25	      };
    26	    case "unavailable":
    27	      return {
    28	        title: "GitHub search is temporarily unavailable.",
    29	        description:
    30	          "GitHub returned a temporary service error. Your search is safe to retry once GitHub recovers.",
    31	      };
    32	    case "validation":
    33	      return {
    34	        title: "GitHub could not validate that search.",
    35	        description:
    36	          "Check the username and try again. GitHub may reject searches for users that do not exist or cannot be searched.",
    37	      };
    38	    case "empty":
    39	      // An incomplete search proves nothing about whether commits exist, so it must not
    40	      // be reported as an absence of them.
    41	      return result.incomplete
    42	        ? {
    43	            title: "GitHub could not finish this search.",
    44	            description:
    45	              "The search timed out before scanning every commit, so nothing came back yet. Try again in a moment.",
    46	          }
    47	        : {
    48	            title: "No public commits found.",
    49	            description:
    50	              "Try another username or check back later; GitHub commit search indexing can lag.",
    51	          };
    52	    default:
    53	      return {
    54	        title: "We could not complete that search.",
    55	        description: result.error,
    56	      };
    57	  }
