    33	  isIncomplete,
    34	  retry,
    35	  onCopy,
    36	}: SearchResultsProps) {
    37	  const resultHeadingRef = useRef<HTMLHeadingElement>(null);
    38	  const firstCommit = commits[0];
    39	
    40	  // Keyed on what changed rather than on object identity: a retry that comes back partial
    41	  // again returns a fresh object for the same commit, and focusing the heading on that
    42	  // would throw the visitor back to the top of the result and drown the announcement
    43	  // explaining what just happened.
    44	  const firstCommitSha = firstCommit.sha;
    45	  useEffect(() => {
    46	    resultHeadingRef.current?.focus();
    47	  }, [firstCommitSha, lastSearchedUsername, isIncomplete]);
    48	
    49	  const uniqueRepositoryCount = new Set(commits.map((commit) => commit.repository.full_name)).size;
    50	  // A retry changes nothing else on screen when it comes back still partial, so every
    51	  // outcome is spoken here rather than left to be inferred from the button's label.
    52	  const retryOutcome = retry.error
    53	    ? `${retry.error} The commits below are still the earlier partial result.`
    54	    : retry.stillPartial
    55	      ? "Searched again. GitHub still returned a partial result, so an earlier commit may still be missing."
    56	      : "";
    57	  const headingDescription = [PARTIAL_RESULT_DESCRIPTION_ID, retryOutcome ? RETRY_OUTCOME_ID : null]
    58	    .filter(Boolean)
    59	    .join(" ");
    60	
    61	  return (
    62	    <div className="w-full flex flex-col items-center pb-12 pt-8">
    63	      <div className="mb-6 w-full max-w-2xl text-left">
    64	        <h1
    65	          ref={resultHeadingRef}
    66	          tabIndex={-1}
