    81	          </a>
    82	          {uniqueRepositoryCount > 1
    83	            ? `, with nearby early commits across ${uniqueRepositoryCount} repositories.`
    84	            : "."}
    85	        </p>
    86	        {isIncomplete ? (
    87	          // The caveat is announced through the heading's description rather than a live
    88	          // region: the block mounts with its content already inside it, which screen
    89	          // readers often skip, while the heading reliably takes focus when results arrive.
    90	          <section
    91	            aria-labelledby={PARTIAL_RESULT_HEADING_ID}
    92	            className="mt-3 rounded-md border border-amber-300 bg-amber-50 p-5 text-amber-900 shadow-sm"
    93	          >
    94	            <h2 id={PARTIAL_RESULT_HEADING_ID} className="text-base font-semibold">
    95	              GitHub returned a partial result
    96	            </h2>
    97	            {/* Sets up the button directly below it. Pointing at the header's "Search
    98	                another user" instead would clear the very handle being reused. */}
    99	            <p id={PARTIAL_RESULT_DESCRIPTION_ID} className="mt-2 text-sm break-words">
