   101	              missing. Searching again often reaches the full history.
   102	            </p>
   103	            <button
   104	              type="button"
   105	              onClick={() => {
   106	                if (retry.isRetrying) return;
   107	                retry.onRetry(lastSearchedUsername);
   108	              }}
