   110	              // moment it is pressed, stranding a keyboard user mid-action.
   111	              aria-disabled={retry.isRetrying}
   112	              className="mt-4 inline-flex items-center justify-center rounded-md border border-amber-700 bg-white px-3 py-2 text-sm font-semibold text-amber-900 transition-colors hover:bg-amber-100 focus:outline-none focus:ring-2 focus:ring-[var(--github-blue)] focus:ring-offset-2 focus:ring-offset-amber-50 aria-disabled:cursor-not-allowed aria-disabled:bg-amber-50 aria-disabled:hover:bg-amber-50"
   113	            >
   114	              {retry.isRetrying ? "Searching again..." : "Search again"}
   115	            </button>
   116	            {/* One region, mounted whether or not it has anything to say: a live region
   117	                inserted together with its text is commonly not announced at all, and a
   118	                separate visible copy of the same message would be read twice. It sits
   119	                below the button so a wrapping message cannot push the control out from
   120	                under a visitor about to press it again. */}
   121	            <div role="status" aria-live="polite">
