1	import { logger } from "@/app/_lib/logger";
2	
3	export const dynamic = "force-dynamic";
4	export const revalidate = 0;
5	
6	// Reports arrive unauthenticated from any browser, so the body is untrusted and unbounded. Anything
7	// larger than this is not a real violation report. The limit counts bytes rather than JavaScript
8	// characters, because a multibyte body is several times larger on the wire than its string length.
9	const MAX_BODY_BYTES = 16_384;
10	
11	// A Reporting API request carries an array, and each entry would otherwise become its own log
12	// record, so one POST could amplify into as many log lines as fit in the body limit. Ten is far
13	// more than a browser batches for one page load; anything beyond it is counted, not logged.
14	const MAX_REPORTS_PER_REQUEST = 10;
15	
16	// `report-uri` posts `application/csp-report` and the Reporting API posts `application/reports+json`.
17	// Nothing else is a violation report, so nothing else is read.
18	const ACCEPTED_CONTENT_TYPES = new Set(["application/csp-report", "application/reports+json"]);
19	
20	// CSP substitutes a bare keyword for a URL in some violations, so these are not parse failures.
21	const URL_KEYWORDS = new Set([
22	  "inline",
23	  "eval",
24	  "self",
25	  "data",
26	  "blob",
27	  "wasm-eval",
28	  "wasm-unsafe-eval",
29	  "trusted-types-policy",
30	  "trusted-types-sink",
31	]);
32	
33	// The only schemes whose path is a location rather than content. Everything else — `data:` and
34	// `blob:` payloads, `javascript:` source, `mailto:` addresses, an app-specific scheme registered by
35	// an extension or a native app — carries its content after the colon, so only the scheme is kept.
36	const PATH_BEARING_PROTOCOLS = new Set(["http:", "https:"]);
37	
38	/**
39	 * Reduce a reported URL to origin + path, or to the bare scheme when the scheme is not http(s).
40	 *
41	 * Query strings are dropped because the app puts the searched username in `?user=`, and search
42	 * usernames must not reach logs. Fragments are dropped for the same reason.
43	 */
44	function safeUrl(value: unknown): string | null {
45	  if (typeof value !== "string") {
46	    return null;
47	  }
48	
49	  const trimmed = value.trim();
50	
51	  if (trimmed === "") {
52	    return null;
53	  }
54	
55	  if (URL_KEYWORDS.has(trimmed)) {
56	    return trimmed;
57	  }
58	
59	  try {
60	    const url = new URL(trimmed);
61	
62	    if (!PATH_BEARING_PROTOCOLS.has(url.protocol)) {
63	      return url.protocol;
64	    }
65	
66	    return `${url.origin}${url.pathname}`;
67	  } catch {
68	    return null;
69	  }
70	}
71	
72	function safeNumber(value: unknown): number | null {
73	  return typeof value === "number" && Number.isFinite(value) ? value : null;
74	}
75	
76	function safeString(value: unknown, maxLength = 128): string | null {
77	  return typeof value === "string" && value.trim() !== "" ? value.trim().slice(0, maxLength) : null;
78	}
79	
80	type ViolationFields = {
81	  documentUri: string | null;
82	  blockedUri: string | null;
83	  effectiveDirective: string | null;
84	  disposition: string | null;
85	  statusCode: number | null;
86	  sourceFile: string | null;
87	  lineNumber: number | null;
88	  columnNumber: number | null;
89	};
90	
91	/**
92	 * Collect the violation records from the two report shapes browsers send.
93	 *
94	 * `report-uri` posts `{"csp-report": {...}}` with hyphenated keys. The Reporting API (`report-to`)
95	 * posts an array of `{type, body}` with camelCased keys. Both are accepted so reporting keeps
96	 * working as browsers migrate.
97	 */
98	function collectReportRecords(parsed: unknown): Record<string, unknown>[] {
99	  const records: Record<string, unknown>[] = [];
100	
101	  if (Array.isArray(parsed)) {
102	    for (const entry of parsed) {
103	      if (entry && typeof entry === "object") {
104	        const { type, body } = entry as { type?: unknown; body?: unknown };
105	
106	        if (type === "csp-violation" && body && typeof body === "object") {
107	          records.push(body as Record<string, unknown>);
108	        }
109	      }
110	    }
111	  } else if (parsed && typeof parsed === "object") {
112	    const legacy = (parsed as Record<string, unknown>)["csp-report"];
113	
114	    if (legacy && typeof legacy === "object") {
115	      records.push(legacy as Record<string, unknown>);
116	    }
117	  }
118	
119	  return records;
120	}
121	
122	/**
123	 * Reduce one report record to the fields that are safe to log.
